 "content": "def _canonical(shape):
    variants = []
    for reflect in (1, -1):
        for turns in range(4):
            pts = []
            for r, c in shape:
                x, y = r, reflect * c
                for _ in range(turns):
                    x, y = y, -x
                pts.append((x, y))
            minr = min(r for r, c in pts)
            minc = min(c for r, c in pts)
            variants.append(tuple(sorted((r-minr, c-minc) for r, c in pts)))
    return min(variants)


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == color and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            minr = min(y for y,x in cells)
            minc = min(x for y,x in cells)
            shape = _canonical([(y-minr,x-minc) for y,x in cells])
            comps.append((color, cells, shape))

    classes = {}
    for i, (color, cells, shape) in enumerate(comps):
        classes.setdefault(shape, []).append(i)
    out = [row[:] for row in grid]
    for ids in classes.values():
        if len(ids) == 2:
            i, j = ids
            ci, cells_i, _ = comps[i]
            cj, cells_j, _ = comps[j]
            for r, c in cells_i:
                out[r][c] = cj
            for r, c in cells_j:
                out[r][c] = ci
    return out

if __name__ == '__main__':
